import { Title } from "@solidjs/meta";
import { createAsync } from "@solidjs/router";
import { createSignal, Show } from "solid-js";
import { createStore } from "solid-js/store";
import {
  successMessage,
  trimValues,
  validateContact,
  type ContactErrors,
  type ContactValues,
} from "~/lib/contact";
import { getContactState, sendContact, type ContactState } from "~/lib/contact.server";

export default function Contact() {
  const state = createAsync(() => getContactState(), { deferStream: true });

  return (
    <>
      <Title>Contact | Bookshelf</Title>
      <h1>Contact</h1>
      <Show when={state()} keyed>
        {(initial) => <ContactForm initial={initial} />}
      </Show>
    </>
  );
}

function ContactForm(props: { initial: ContactState }) {
  const [values, setValues] = createStore<ContactValues>({ ...props.initial.values });
  const [errors, setErrors] = createSignal<ContactErrors>(props.initial.errors);
  const [success, setSuccess] = createSignal<string | null>(props.initial.success);
  const [sending, setSending] = createSignal(false);

  const update = (field: keyof ContactValues) => (event: { currentTarget: { value: string } }) =>
    setValues(field, event.currentTarget.value);

  const onSubmit = async (event: SubmitEvent) => {
    event.preventDefault();
    if (sending()) return;
    const sent = trimValues({ ...values });
    const found = validateContact(sent);
    setErrors(found);
    if (Object.keys(found).length > 0) {
      setSuccess(null);
      return;
    }
    setSending(true);
    try {
      const result = await sendContact(sent);
      setErrors(result.errors);
      if (result.success) {
        setSuccess(successMessage(sent));
        setValues({ name: "", email: "", message: "" });
      } else {
        setSuccess(null);
      }
    } catch {
      setSuccess(null);
      setErrors({ message: "Your message could not be sent. Please try again." });
    } finally {
      setSending(false);
    }
  };

  return (
    <>
      <Show when={success()}>
        <p class="success" role="status">
          {success()}
        </p>
      </Show>
      <form method="post" action="/contact" novalidate onSubmit={onSubmit} class="contact-form">
        <div class="field">
          <label for="contact-name">Name</label>
          <input
            id="contact-name"
            name="name"
            type="text"
            value={values.name}
            onInput={update("name")}
            aria-invalid={errors().name ? "true" : undefined}
            aria-describedby={errors().name ? "contact-name-error" : undefined}
          />
          <Show when={errors().name}>
            <p id="contact-name-error" class="error">
              {errors().name}
            </p>
          </Show>
        </div>
        <div class="field">
          <label for="contact-email">Email</label>
          <input
            id="contact-email"
            name="email"
            type="email"
            value={values.email}
            onInput={update("email")}
            aria-invalid={errors().email ? "true" : undefined}
            aria-describedby={errors().email ? "contact-email-error" : undefined}
          />
          <Show when={errors().email}>
            <p id="contact-email-error" class="error">
              {errors().email}
            </p>
          </Show>
        </div>
        <div class="field">
          <label for="contact-message">Message</label>
          <textarea
            id="contact-message"
            name="message"
            value={values.message}
            onInput={update("message")}
            aria-invalid={errors().message ? "true" : undefined}
            aria-describedby={errors().message ? "contact-message-error" : undefined}
          />
          <Show when={errors().message}>
            <p id="contact-message-error" class="error">
              {errors().message}
            </p>
          </Show>
        </div>
        <button type="submit" disabled={sending()}>
          Send
        </button>
      </form>
    </>
  );
}
